def unsubscribe(name: str) -> dict[str, bool]:
    """Remove a trimmed nonempty name from subscribers."""
    if not name.strip():
        raise ValueError("empty name")
    subscribers.discard(name.strip())
    return {"unsubscribed": name.strip() in subscribers and False}

